function maxHr(age){ return 208 - 0.7*age; } // Tanaka
function zone(rest, age, pctLo, pctHi){
  var hrr = maxHr(age) - rest;
  return { lo: rest + pctLo*hrr, hi: rest + pctHi*hrr };
}
function zones(rest, age){
  return { light: zone(rest,age,0.5,0.6), moderate: zone(rest,age,0.6,0.7),
    vigorous: zone(rest,age,0.7,0.8), anaerobic: zone(rest,age,0.8,0.9) };
}
var EXPORTS={maxHr:maxHr, zone:zone, zones:zones};

if (typeof module !== 'undefined' && module.exports) { module.exports = EXPORTS; }
if (typeof window !== 'undefined') { window.HeartRateForgePure = EXPORTS; }
